window.BRIGHTSTEPS_CURRICULUM = [{"id":"g3-math-1","grade":3,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Numbers to 10,000","titleHi":"10,000 तक संख्याएँ","teach":"Numbers have place values. A digit’s value depends on its position: ones, tens, hundreds and thousands. Compare from the greatest place first.","teachHi":"संख्याओं में स्थानीय मान होता है। अंक का मान उसके स्थान—इकाई, दहाई, सैकड़ा और हजार—पर निर्भर करता है। तुलना सबसे बड़े स्थान से शुरू करें।","example":"4,382 = 4 thousands + 3 hundreds + 8 tens + 2 ones.","exampleHi":"4,382 = 4 हजार + 3 सैकड़ा + 8 दहाई + 2 इकाई।","question":"What is the value of 7 in 3,742?","options":["7","70","700","7,000"],"answer":2,"explain":"The 7 is in the hundreds place, so its value is 700.","explainHi":"7 सैकड़े के स्थान पर है, इसलिए उसका मान 700 है।","skills":"Numbers to 10,000"},{"id":"g3-math-2","grade":3,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Addition and subtraction","titleHi":"जोड़ और घटाव","teach":"Line up digits by place value. Regroup when a column reaches ten; estimate first to check whether an answer is reasonable.","teachHi":"अंकों को स्थानीय मान के अनुसार लिखें। किसी स्थान पर दस होने पर पुनर्गठन करें। उत्तर जाँचने के लिए पहले अनुमान लगाएँ।","example":"468 + 257 = 725.","exampleHi":"468 + 257 = 725.","question":"What is 503 − 178?","options":["325","335","425","431"],"answer":0,"explain":"503 − 178 = 325. Regroup across the zero carefully.","explainHi":"503 − 178 = 325। शून्य के पार पुनर्गठन ध्यान से करें।","skills":"Addition and subtraction"},{"id":"g3-math-3","grade":3,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Multiplication","titleHi":"गुणा","teach":"Multiplication is equal groups or repeated addition. Use known tables and split a number into easier parts.","teachHi":"गुणा बराबर समूहों या बार-बार जोड़ने का छोटा तरीका है। पहाड़ों और संख्या को आसान भागों में बाँटने का उपयोग करें।","example":"6 × 4 means 6 groups of 4, which is 24.","exampleHi":"6 × 4 का अर्थ 4 के 6 समूह, यानी 24।","question":"There are 7 boxes with 5 pencils each. How many pencils?","options":["12","30","35","40"],"answer":2,"explain":"7 × 5 = 35 pencils.","explainHi":"7 × 5 = 35 पेंसिल।","skills":"Multiplication"},{"id":"g3-math-4","grade":3,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Fractions","titleHi":"भिन्न","teach":"A fraction describes equal parts of a whole. The denominator names the total equal parts; the numerator names the parts selected.","teachHi":"भिन्न पूरे के बराबर भागों को बताती है। हर कुल बराबर भाग और अंश चुने गए भाग बताता है।","example":"3/4 means 3 of 4 equal parts.","exampleHi":"3/4 का अर्थ 4 बराबर भागों में से 3 भाग।","question":"In 2/5, what is the denominator?","options":["2","5","7","10"],"answer":1,"explain":"The denominator is the bottom number: 5.","explainHi":"हर नीचे की संख्या है: 5।","skills":"Fractions"},{"id":"g3-math-5","grade":3,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Measurement and time","titleHi":"मापन और समय","teach":"Choose suitable units: centimetres for small lengths, metres for longer lengths, grams/kilograms for mass, and minutes/hours for time.","teachHi":"उचित इकाई चुनें: छोटी लंबाई के लिए सेंटीमीटर, बड़ी के लिए मीटर, द्रव्यमान के लिए ग्राम/किलोग्राम और समय के लिए मिनट/घंटे।","example":"1 metre = 100 centimetres.","exampleHi":"1 मीटर = 100 सेंटीमीटर।","question":"How many centimetres are in 2 metres?","options":["20","100","200","2,000"],"answer":2,"explain":"2 × 100 = 200 cm.","explainHi":"2 × 100 = 200 सेमी।","skills":"Measurement and time"},{"id":"g3-math-6","grade":3,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Shapes and patterns","titleHi":"आकार और पैटर्न","teach":"2-D shapes are flat. A polygon has straight sides. Look for the rule that repeats in a pattern.","teachHi":"2-D आकृतियाँ समतल होती हैं। बहुभुज की भुजाएँ सीधी होती हैं। पैटर्न में दोहराए जाने वाला नियम पहचानें।","example":"2, 4, 6, 8 increases by 2 each time.","exampleHi":"2, 4, 6, 8 में हर बार 2 बढ़ता है।","question":"Which shape has 3 sides?","options":["Circle","Triangle","Rectangle","Pentagon"],"answer":1,"explain":"A triangle has three sides.","explainHi":"त्रिभुज की तीन भुजाएँ होती हैं।","skills":"Shapes and patterns"},{"id":"g3-english-1","grade":3,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Parts of speech","titleHi":"शब्द-भेद","teach":"A noun names a person, place, animal or thing. A verb shows an action or state. An adjective describes a noun.","teachHi":"Noun किसी व्यक्ति, स्थान, जानवर या वस्तु का नाम है। Verb काम या अवस्था बताता है। Adjective संज्ञा की विशेषता बताता है।","example":"The small bird sings. Small describes bird; sings is the verb.","exampleHi":"The small bird sings. यहाँ small विशेषण और sings क्रिया है।","question":"Which word is the verb in “Riya runs fast”?","options":["Riya","runs","fast","the"],"answer":1,"explain":"Runs tells the action.","explainHi":"Runs काम बताता है।","skills":"Parts of speech"},{"id":"g3-english-2","grade":3,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Sentences and punctuation","titleHi":"वाक्य और विराम-चिह्न","teach":"A sentence expresses a complete thought. Begin with a capital letter and use a full stop, question mark or exclamation mark as needed.","teachHi":"वाक्य पूरा विचार व्यक्त करता है। बड़े अक्षर से शुरू करें और आवश्यकता अनुसार पूर्ण विराम, प्रश्नवाचक या विस्मयादिबोधक चिह्न लगाएँ।","example":"Where are you? is a question.","exampleHi":"Where are you? एक प्रश्न है।","question":"Which punctuation ends a question?","options":[".","? ",",",":"],"answer":1,"explain":"A question mark ends a direct question.","explainHi":"प्रश्नवाचक चिह्न प्रश्न के अंत में आता है।","skills":"Sentences and punctuation"},{"id":"g3-english-3","grade":3,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Reading comprehension","titleHi":"पठन-बोध","teach":"Read the whole passage, identify who/what/when/where, and use clues from the text rather than guessing.","teachHi":"पूरा अनुच्छेद पढ़ें, कौन/क्या/कब/कहाँ पहचानें और अनुमान के बजाय पाठ के संकेतों का उपयोग करें।","example":"If a story says “Mina carried an umbrella because clouds were dark,” the clue suggests possible rain.","exampleHi":"यदि कहानी कहती है कि मीना ने काला आसमान देखकर छाता लिया, तो बारिश की संभावना का संकेत है।","question":"What should you use to answer a passage question?","options":["A random guess","Clues in the passage","Only the title","A friend’s answer"],"answer":1,"explain":"Answers should be supported by the text.","explainHi":"उत्तर का आधार पाठ में होना चाहिए।","skills":"Reading comprehension"},{"id":"g3-english-4","grade":3,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Tenses and time words","titleHi":"काल और समय-सूचक शब्द","teach":"Past tense tells about something already done; present tells what happens now or regularly; future tells what will happen.","teachHi":"भूतकाल पहले हो चुके काम, वर्तमानकाल अभी या नियमित काम और भविष्यकाल आगे होने वाले काम को बताता है।","example":"Yesterday I walked; today I walk; tomorrow I will walk.","exampleHi":"Yesterday I walked; today I walk; tomorrow I will walk.","question":"“Tomorrow we ___ the museum.”","options":["visited","visit yesterday","will visit","visiting"],"answer":2,"explain":"Tomorrow signals future: will visit.","explainHi":"Tomorrow भविष्य बताता है: will visit।","skills":"Tenses and time words"},{"id":"g3-english-5","grade":3,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Vocabulary and spelling","titleHi":"शब्दावली और वर्तनी","teach":"Use context to infer meaning. Learn word families, synonyms (similar meanings) and antonyms (opposite meanings).","teachHi":"संदर्भ से अर्थ समझें। समानार्थी और विलोम शब्द सीखें।","example":"Happy and joyful are synonyms; happy and sad are opposites.","exampleHi":"Happy और joyful समानार्थी हैं; happy और sad विपरीत हैं।","question":"Which is an antonym of “bright”?","options":["shiny","clever","dark","sunny"],"answer":2,"explain":"Dark is the opposite of bright in light.","explainHi":"प्रकाश के अर्थ में dark, bright का विलोम है।","skills":"Vocabulary and spelling"},{"id":"g3-hindi-1","grade":3,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"संज्ञा और सर्वनाम","titleHi":"Nouns and pronouns","teach":"संज्ञा किसी व्यक्ति, स्थान, वस्तु या भाव का नाम है। सर्वनाम संज्ञा के स्थान पर आता है।","teachHi":"A noun names a person, place, thing or idea. A pronoun replaces a noun.","example":"राम खेलता है। वह खुश है। यहाँ “वह” सर्वनाम है।","exampleHi":"Ram plays. He is happy. “He” is a pronoun.","question":"“सीता गाती है। ___ मधुर गाती है।”","options":["मैं","वह","हम","तुम"],"answer":1,"explain":"“वह” सीता के स्थान पर आया है।","explainHi":"“वह” replaces Sita.","skills":"संज्ञा और सर्वनाम"},{"id":"g3-hindi-2","grade":3,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"लिंग और वचन","titleHi":"Gender and number","teach":"हिंदी में शब्दों का लिंग पुल्लिंग या स्त्रीलिंग हो सकता है। वचन एक या अनेक होने का बोध कराता है।","teachHi":"Hindi nouns can be masculine or feminine. Number shows one or more than one.","example":"लड़का–लड़के; लड़की–लड़कियाँ।","exampleHi":"लड़का–लड़के; लड़की–लड़कियाँ।","question":"“किताब” का बहुवचन क्या है?","options":["किताबें","किताबी","किताबों का","किताबपन"],"answer":0,"explain":"किताब का बहुवचन किताबें है।","explainHi":"The plural of किताब is किताबें.","skills":"लिंग और वचन"},{"id":"g3-hindi-3","grade":3,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"वाक्य और विराम-चिह्न","titleHi":"Sentences and punctuation","teach":"वाक्य पूरा अर्थ देता है। प्रश्न के अंत में प्रश्नवाचक चिह्न और कथन के अंत में पूर्ण विराम लगाते हैं।","teachHi":"A sentence gives complete meaning. Use a question mark for questions and a full stop for statements.","example":"तुम कहाँ जा रहे हो?","exampleHi":"Where are you going?","question":"प्रश्न के अंत में कौन-सा चिह्न आता है?","options":["।","?",",","! हर बार"],"answer":1,"explain":"हिंदी में प्रश्नवाचक चिह्न “?” है।","explainHi":"A question mark ends a question.","skills":"वाक्य और विराम-चिह्न"},{"id":"g3-hindi-4","grade":3,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"पठन-बोध","titleHi":"Reading comprehension","teach":"गद्यांश ध्यान से पढ़ें। उत्तर उसी में दिए संकेतों के आधार पर दें और मुख्य विचार पहचानें।","teachHi":"Read a passage carefully. Answer using its clues and identify the main idea.","example":"यदि पाठ में पेड़ लगाने से छाया मिलने की बात है, तो यह लाभ पाठ से मिला।","exampleHi":"If a passage says trees provide shade, that benefit is stated in the text.","question":"गद्यांश के प्रश्न का उत्तर कहाँ से लें?","options":["केवल अनुमान से","पाठ के संकेतों से","बिना पढ़े","किसी भी विषय से"],"answer":1,"explain":"उत्तर पाठ पर आधारित होना चाहिए।","explainHi":"Answers should be based on the passage.","skills":"पठन-बोध"},{"id":"g3-hindi-5","grade":3,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"शब्दार्थ और विलोम","titleHi":"Word meaning and antonyms","teach":"पर्यायवाची समान अर्थ वाले और विलोम विपरीत अर्थ वाले शब्द हैं। संदर्भ से नए शब्द का अर्थ समझें।","teachHi":"Synonyms have similar meanings; antonyms have opposite meanings. Use context to infer new words.","example":"दिन–रात विलोम हैं; खुश–प्रसन्न पर्यायवाची हैं।","exampleHi":"Day–night are opposites; happy–joyful are synonyms.","question":"“ऊँचा” का विलोम है…","options":["लंबा","नीचा","बड़ा","चौड़ा"],"answer":1,"explain":"नीचा, ऊँचा का विलोम है।","explainHi":"नीचा is the opposite of ऊँचा.","skills":"शब्दार्थ और विलोम"},{"id":"g3-world-1","grade":3,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Living and non-living things","titleHi":"सजीव और निर्जीव","teach":"Living things grow, need resources and carry out life processes. Non-living things do not carry out all life processes.","teachHi":"सजीव बढ़ते हैं, संसाधनों की ज़रूरत होती है और जीवन क्रियाएँ करते हैं। निर्जीव सभी जीवन क्रियाएँ नहीं करते।","example":"A seed can grow into a plant under suitable conditions.","exampleHi":"उचित परिस्थितियों में बीज पौधा बन सकता है।","question":"Which is living?","options":["Stone","Chair","Seed","Pencil"],"answer":2,"explain":"A seed is living and can germinate.","explainHi":"बीज सजीव है और अंकुरित हो सकता है।","skills":"Living and non-living things"},{"id":"g3-world-2","grade":3,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Plants and their needs","titleHi":"पौधे और उनकी आवश्यकताएँ","teach":"Plants generally need light, water, air and suitable nutrients. Roots absorb water and anchor the plant; leaves make food.","teachHi":"पौधों को सामान्यतः प्रकाश, पानी, हवा और पोषक तत्व चाहिए। जड़ें पानी सोखती हैं और पौधे को थामती हैं; पत्तियाँ भोजन बनाती हैं।","example":"A plant kept without light may become weak.","exampleHi":"प्रकाश के बिना रखा पौधा कमजोर हो सकता है।","question":"Which part usually absorbs water from soil?","options":["Flower","Root","Fruit","Seed coat"],"answer":1,"explain":"Roots absorb water from the soil.","explainHi":"जड़ें मिट्टी से पानी सोखती हैं।","skills":"Plants and their needs"},{"id":"g3-world-3","grade":3,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Animals and habitats","titleHi":"जानवर और आवास","teach":"A habitat provides food, water, shelter and suitable conditions. Body features can help an animal survive there.","teachHi":"आवास भोजन, पानी, आश्रय और उपयुक्त परिस्थितियाँ देता है। शरीर की विशेषताएँ जीवित रहने में मदद करती हैं।","example":"A camel is adapted to dry desert conditions.","exampleHi":"ऊँट शुष्क रेगिस्तानी परिस्थितियों के अनुकूल है।","question":"A fish gets oxygen mainly from water using…","options":["lungs only","gills","feathers","roots"],"answer":1,"explain":"Most fish use gills to take oxygen from water.","explainHi":"अधिकांश मछलियाँ पानी से ऑक्सीजन लेने के लिए गलफड़े उपयोग करती हैं।","skills":"Animals and habitats"},{"id":"g3-world-4","grade":3,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Water, weather and seasons","titleHi":"पानी, मौसम और ऋतुएँ","teach":"Water changes state: evaporation forms water vapour and cooling can condense vapour into droplets. Weather changes day to day.","teachHi":"पानी की अवस्था बदलती है: वाष्पीकरण से जलवाष्प और ठंडा होने पर संघनन से बूंदें बनती हैं। मौसम रोज बदल सकता है।","example":"Water droplets on a cold glass form by condensation.","exampleHi":"ठंडे गिलास पर पानी की बूंदें संघनन से बनती हैं।","question":"Which is a way to save water?","options":["Leave tap running","Fix leaking taps","Wash one item under running water for long","Throw clean water away"],"answer":1,"explain":"Fixing leaks prevents waste.","explainHi":"रिसाव ठीक करने से पानी बचता है।","skills":"Water, weather and seasons"},{"id":"g3-world-5","grade":3,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Family, neighbourhood and safety","titleHi":"परिवार, पड़ोस और सुरक्षा","teach":"Communities work through shared responsibilities. Follow road, fire and personal safety rules and seek trusted adult help when needed.","teachHi":"समुदाय साझा जिम्मेदारियों से चलता है। सड़क, आग और व्यक्तिगत सुरक्षा नियम मानें और ज़रूरत पर भरोसेमंद बड़े से मदद लें।","example":"Look both ways and cross at a safe crossing with an adult when needed.","exampleHi":"दोनों ओर देखकर सुरक्षित स्थान से पार करें और ज़रूरत पर बड़े की मदद लें।","question":"When unsure about safety, what should you do?","options":["Hide it","Ask a trusted adult","Follow a stranger","Ignore danger"],"answer":1,"explain":"A trusted adult can help you make a safer choice.","explainHi":"भरोसेमंद बड़ा सुरक्षित निर्णय में मदद कर सकता है।","skills":"Family, neighbourhood and safety"},{"id":"g3-gk-1","grade":3,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"India and the world","titleHi":"भारत और दुनिया","teach":"Learn facts as connected ideas, not isolated memorisation. Check names, places and dates against reliable sources.","teachHi":"तथ्यों को अलग-अलग रटने के बजाय आपस में जोड़कर सीखें। नाम, स्थान और तिथियाँ भरोसेमंद स्रोत से जाँचें।","example":"New Delhi is the capital of India.","exampleHi":"नई दिल्ली भारत की राजधानी है।","question":"What is India’s capital?","options":["Mumbai","New Delhi","Chennai","Jaipur"],"answer":1,"explain":"New Delhi is the capital of India.","explainHi":"नई दिल्ली भारत की राजधानी है।","skills":"India and the world"},{"id":"g3-gk-2","grade":3,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Nature and animals","titleHi":"प्रकृति और जानवर","teach":"Biodiversity means the variety of living things. Protect habitats and avoid disturbing wild animals.","teachHi":"जैव विविधता का अर्थ जीवों की विविधता है। आवासों की रक्षा करें और जंगली जीवों को परेशान न करें।","example":"A national park protects habitats and wildlife.","exampleHi":"राष्ट्रीय उद्यान आवास और वन्यजीवों की रक्षा करता है।","question":"Which is a mammal?","options":["Frog","Sparrow","Dolphin","Butterfly"],"answer":2,"explain":"Dolphins are mammals that breathe air.","explainHi":"डॉल्फ़िन स्तनधारी हैं और हवा में साँस लेती हैं।","skills":"Nature and animals"},{"id":"g3-gk-3","grade":3,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Science in everyday life","titleHi":"रोज़मर्रा का विज्ञान","teach":"Observe carefully, ask testable questions and compare evidence. Avoid assuming that one example proves a universal claim.","teachHi":"ध्यान से देखें, जाँचे जा सकने वाले प्रश्न पूछें और प्रमाण की तुलना करें। एक उदाहरण से सार्वभौमिक दावा सही न मानें।","example":"A fair test changes one factor while keeping others the same.","exampleHi":"निष्पक्ष परीक्षण में एक कारक बदलें और अन्य समान रखें।","question":"A fair test should…","options":["change everything","change one factor at a time","hide results","skip measurements"],"answer":1,"explain":"Changing one factor helps identify its effect.","explainHi":"एक कारक बदलने से उसका प्रभाव समझ आता है।","skills":"Science in everyday life"},{"id":"g3-gk-4","grade":3,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Digital safety and logic","titleHi":"डिजिटल सुरक्षा और तर्क","teach":"Keep passwords private, ask a trusted adult before sharing information, and pause before clicking unknown links.","teachHi":"पासवर्ड निजी रखें, जानकारी साझा करने से पहले भरोसेमंद बड़े से पूछें और अनजान लिंक पर क्लिक करने से पहले रुकें।","example":"A stranger online is still a stranger.","exampleHi":"ऑनलाइन अनजान व्यक्ति भी अनजान ही है।","question":"Should you share your password with an online stranger?","options":["Yes","Only if they ask nicely","No","Post it publicly"],"answer":2,"explain":"Passwords must remain private.","explainHi":"पासवर्ड निजी रहने चाहिए।","skills":"Digital safety and logic"},{"id":"g3-gk-5","grade":3,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Puzzles and reasoning","titleHi":"पहेलियाँ और तर्क","teach":"Look for patterns, sort information, eliminate impossible answers and explain why your answer fits.","teachHi":"पैटर्न पहचानें, जानकारी क्रमबद्ध करें, असंभव उत्तर हटाएँ और समझाएँ कि आपका उत्तर क्यों सही है।","example":"2, 4, 6, 8 follows “add 2.”","exampleHi":"2, 4, 6, 8 में हर बार 2 जोड़ते हैं।","question":"What comes next: 5, 10, 15, 20, __?","options":["21","24","25","30"],"answer":2,"explain":"The pattern adds 5, so 25 follows.","explainHi":"हर बार 5 जुड़ता है, इसलिए 25।","skills":"Puzzles and reasoning"},{"id":"g3-computer-1","grade":3,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Computer basics","titleHi":"कंप्यूटर की मूल बातें","teach":"A computer takes input, processes it, stores data and gives output. Different devices serve different purposes.","teachHi":"कंप्यूटर इनपुट लेता है, प्रक्रिया करता है, डेटा रखता है और आउटपुट देता है। अलग उपकरण अलग काम करते हैं।","example":"Keyboard = input; monitor = output.","exampleHi":"कीबोर्ड इनपुट और मॉनिटर आउटपुट है।","question":"Which is an input device?","options":["Monitor","Speaker","Keyboard","Printer"],"answer":2,"explain":"A keyboard sends information into a computer.","explainHi":"कीबोर्ड कंप्यूटर में जानकारी देता है।","skills":"Computer basics"},{"id":"g3-computer-2","grade":3,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Files, folders and typing","titleHi":"फाइल, फ़ोल्डर और टाइपिंग","teach":"Files store work; folders organise files. Use meaningful names and save work in a known place.","teachHi":"फाइल काम सहेजती है; फ़ोल्डर फाइल व्यवस्थित करता है। अर्थपूर्ण नाम दें और काम सही जगह सहेजें।","example":"“Science-notes” is clearer than “abc123”.","exampleHi":"“Science-notes”, “abc123” से स्पष्ट है।","question":"Why use folders?","options":["To organise files","To increase screen brightness","To clean a keyboard","To replace passwords"],"answer":0,"explain":"Folders organise related files.","explainHi":"फ़ोल्डर संबंधित फाइलें व्यवस्थित करते हैं।","skills":"Files, folders and typing"},{"id":"g3-computer-3","grade":3,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Online safety and privacy","titleHi":"ऑनलाइन सुरक्षा और गोपनीयता","teach":"Do not share passwords, home address or private photos with strangers. Ask a trusted adult before downloading or contacting unknown people.","teachHi":"पासवर्ड, घर का पता या निजी तस्वीरें अनजान लोगों से साझा न करें। डाउनलोड या संपर्क से पहले भरोसेमंद बड़े से पूछें।","example":"A strong password is private and hard to guess.","exampleHi":"मजबूत पासवर्ड निजी और अनुमान लगाना कठिन होता है।","question":"What should remain private?","options":["Your password","A public library address","A class topic","A public weather report"],"answer":0,"explain":"Passwords protect accounts and should not be shared.","explainHi":"पासवर्ड खाते की रक्षा करते हैं और साझा नहीं करने चाहिए।","skills":"Online safety and privacy"},{"id":"g3-computer-4","grade":3,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Algorithms and debugging","titleHi":"एल्गोरिद्म और त्रुटि सुधार","teach":"An algorithm is a clear sequence of steps. Debugging means finding and fixing an error by testing one step at a time.","teachHi":"एल्गोरिद्म स्पष्ट चरणों का क्रम है। डिबगिंग में एक-एक चरण जाँचकर गलती खोजते और सुधारते हैं।","example":"A recipe is an algorithm for making food.","exampleHi":"रेसिपी भोजन बनाने का एल्गोरिद्म है।","question":"Debugging means…","options":["adding random steps","finding and fixing errors","deleting all files","turning off learning"],"answer":1,"explain":"Debugging finds and fixes mistakes.","explainHi":"डिबगिंग गलतियाँ खोजकर सुधारती है।","skills":"Algorithms and debugging"},{"id":"g3-art-1","grade":3,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Art, music and observation","titleHi":"कला, संगीत और अवलोकन","teach":"Artists observe shape, line, colour, pattern and texture. Creative work can have many valid solutions; explain your choices.","teachHi":"कलाकार आकार, रेखा, रंग, पैटर्न और बनावट देखते हैं। रचनात्मक काम के कई सही तरीके हो सकते हैं; अपने चुनाव समझाएँ।","example":"Repeating shapes creates a pattern.","exampleHi":"आकार दोहराने से पैटर्न बनता है।","question":"Which element describes how a surface feels or looks?","options":["Texture","Date","Weight only","Address"],"answer":0,"explain":"Texture describes surface quality.","explainHi":"बनावट सतह का गुण बताती है।","skills":"Art, music and observation"},{"id":"g3-art-2","grade":3,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Health, movement and teamwork","titleHi":"स्वास्थ्य, गतिविधि और टीमवर्क","teach":"Movement, rest, hydration and balanced food support wellbeing. In games, cooperate, take turns and follow safety rules.","teachHi":"गतिविधि, आराम, पानी और संतुलित भोजन स्वास्थ्य में मदद करते हैं। खेल में सहयोग करें, बारी लें और सुरक्षा नियम मानें।","example":"Warm up before vigorous exercise.","exampleHi":"तेज़ व्यायाम से पहले वार्म-अप करें।","question":"What is a good practice before vigorous exercise?","options":["Warm up","Skip water always","Ignore pain","Push others"],"answer":0,"explain":"Warming up prepares the body for movement.","explainHi":"वार्म-अप शरीर को गतिविधि के लिए तैयार करता है।","skills":"Health, movement and teamwork"},{"id":"g3-art-3","grade":3,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Life skills and study habits","titleHi":"जीवन कौशल और अध्ययन आदतें","teach":"Break a large task into smaller steps, take short breaks, ask for help and review mistakes without shame.","teachHi":"बड़े काम को छोटे चरणों में बाँटें, छोटे विराम लें, मदद माँगें और बिना शर्म के गलतियों की समीक्षा करें।","example":"Study 25–30 minutes, then take a short movement break.","exampleHi":"25–30 मिनट पढ़ें, फिर थोड़ा चलने का विराम लें।","question":"When you make a mistake, the best next step is…","options":["give up","review why and try again","hide all work","blame a friend"],"answer":1,"explain":"Mistakes give information about what to practise next.","explainHi":"गलतियाँ बताती हैं कि आगे किसका अभ्यास करना है।","skills":"Life skills and study habits"},{"id":"g3-art-4","grade":3,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Art, music and observation","titleHi":"कला, संगीत और अवलोकन","teach":"Artists observe shape, line, colour, pattern and texture. Creative work can have many valid solutions; explain your choices.","teachHi":"कलाकार आकार, रेखा, रंग, पैटर्न और बनावट देखते हैं। रचनात्मक काम के कई सही तरीके हो सकते हैं; अपने चुनाव समझाएँ।","example":"Repeating shapes creates a pattern.","exampleHi":"आकार दोहराने से पैटर्न बनता है।","question":"Which element describes how a surface feels or looks?","options":["Texture","Date","Weight only","Address"],"answer":0,"explain":"Texture describes surface quality.","explainHi":"बनावट सतह का गुण बताती है।","skills":"Art, music and observation"},{"id":"g4-math-1","grade":4,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Large numbers and place value","titleHi":"बड़ी संख्याएँ और स्थानीय मान","teach":"Read multi-digit numbers by grouping places. Use expanded form and compare digits from left to right.","teachHi":"बड़ी संख्याओं को स्थानों के समूह में पढ़ें। विस्तारित रूप लिखें और बाएँ से दाएँ तुलना करें।","example":"52,406 = 50,000 + 2,000 + 400 + 6.","exampleHi":"52,406 = 50,000 + 2,000 + 400 + 6।","question":"What is the value of 8 in 38,251?","options":["8","80","800","8,000"],"answer":3,"explain":"8 is in the thousands place: 8,000.","explainHi":"8 हजार के स्थान पर है: 8,000।","skills":"Large numbers and place value"},{"id":"g4-math-2","grade":4,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Operations and estimation","titleHi":"संक्रियाएँ और अनुमान","teach":"Estimate before calculating. Use inverse operations to check: addition and subtraction undo each other; multiplication and division are related.","teachHi":"गणना से पहले अनुमान लगाएँ। उलटी संक्रिया से जाँचें: जोड़-घटाव एक-दूसरे को उलटते हैं; गुणा-भाग संबंधित हैं।","example":"249 + 351 is about 250 + 350 = 600.","exampleHi":"249 + 351 लगभग 250 + 350 = 600।","question":"Which is the best estimate for 398 + 204?","options":["300","400","600","900"],"answer":2,"explain":"398 is about 400 and 204 about 200, so about 600.","explainHi":"398 लगभग 400 और 204 लगभग 200, इसलिए लगभग 600।","skills":"Operations and estimation"},{"id":"g4-math-3","grade":4,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Multiplication and division","titleHi":"गुणा और भाग","teach":"Multiplication combines equal groups; division shares equally or asks how many groups fit. Check division by multiplying quotient and divisor.","teachHi":"गुणा बराबर समूह बनाता है; भाग बराबर बाँटता है या समूहों की संख्या बताता है। भागफल और भाजक का गुणा करके जाँचें।","example":"36 ÷ 4 = 9 because 9 × 4 = 36.","exampleHi":"36 ÷ 4 = 9 क्योंकि 9 × 4 = 36।","question":"48 stickers are shared among 6 children. Each gets…","options":["6","7","8","9"],"answer":2,"explain":"48 ÷ 6 = 8.","explainHi":"48 ÷ 6 = 8।","skills":"Multiplication and division"},{"id":"g4-math-4","grade":4,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Equivalent fractions","titleHi":"समतुल्य भिन्न","teach":"Equivalent fractions show the same amount. Multiply or divide numerator and denominator by the same non-zero number.","teachHi":"समतुल्य भिन्न समान मात्रा दिखाती हैं। अंश और हर को एक ही गैर-शून्य संख्या से गुणा या भाग दें।","example":"1/2 = 2/4 = 3/6.","exampleHi":"1/2 = 2/4 = 3/6।","question":"Which fraction equals 1/2?","options":["2/3","3/6","3/4","1/3"],"answer":1,"explain":"3/6 simplifies to 1/2.","explainHi":"3/6 सरल होकर 1/2 होता है।","skills":"Equivalent fractions"},{"id":"g4-math-5","grade":4,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Perimeter and area","titleHi":"परिमाप और क्षेत्रफल","teach":"Perimeter measures the distance around a shape. Area measures the surface covered. Keep units clear.","teachHi":"परिमाप आकृति के चारों ओर की दूरी है। क्षेत्रफल ढके हुए सतह-भाग का माप है। इकाइयों का ध्यान रखें।","example":"A 4 cm by 3 cm rectangle has perimeter 14 cm.","exampleHi":"4 सेमी × 3 सेमी आयत का परिमाप 14 सेमी है।","question":"A square has side 5 cm. Its perimeter is…","options":["10 cm","15 cm","20 cm","25 cm"],"answer":2,"explain":"4 × 5 = 20 cm.","explainHi":"4 × 5 = 20 सेमी।","skills":"Perimeter and area"},{"id":"g4-math-6","grade":4,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Data and graphs","titleHi":"आँकड़े और आलेख","teach":"Tables and bar graphs organise information. Read the labels and scale before comparing quantities.","teachHi":"तालिकाएँ और स्तंभ आलेख जानकारी व्यवस्थित करते हैं। तुलना से पहले शीर्षक, लेबल और पैमाना पढ़ें।","example":"If one bar represents 5 books, a height of 4 units means 20 books.","exampleHi":"यदि एक इकाई 5 किताबें दिखाती है, तो 4 इकाई 20 किताबें हैं।","question":"A chart shows 3, 5 and 4 books on three days. Total?","options":["8","9","12","15"],"answer":2,"explain":"3 + 5 + 4 = 12.","explainHi":"3 + 5 + 4 = 12।","skills":"Data and graphs"},{"id":"g4-english-1","grade":4,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Nouns, pronouns and adjectives","titleHi":"संज्ञा, सर्वनाम और विशेषण","teach":"Pronouns replace nouns to avoid repetition. Adjectives add details. Proper nouns name specific people or places and begin with capitals.","teachHi":"सर्वनाम संज्ञा की जगह लेते हैं। विशेषण विवरण जोड़ते हैं। व्यक्तिवाचक संज्ञा के नाम बड़े अक्षर से शुरू होते हैं।","example":"Anaya has a red bag. She carries it. She replaces Anaya.","exampleHi":"Anaya has a red bag. She carries it. She, Anaya की जगह है।","question":"In “The tall boy smiled,” which word is an adjective?","options":["boy","smiled","the","tall"],"answer":3,"explain":"Tall describes the boy.","explainHi":"Tall लड़के का वर्णन करता है।","skills":"Nouns, pronouns and adjectives"},{"id":"g4-english-2","grade":4,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Subject–verb agreement","titleHi":"कर्ता-क्रिया सामंजस्य","teach":"The verb must agree with its subject. In the simple present, he/she/it often takes a verb ending in -s.","teachHi":"क्रिया कर्ता से मेल खाती है। सामान्य वर्तमान में he/she/it के साथ अक्सर क्रिया में -s आता है।","example":"She plays; they play.","exampleHi":"She plays; they play.","question":"Choose the correct sentence.","options":["They walks home.","He walk home.","He walks home.","She walk home."],"answer":2,"explain":"He is singular, so “walks” is correct.","explainHi":"He एकवचन है, इसलिए walks सही है।","skills":"Subject–verb agreement"},{"id":"g4-english-3","grade":4,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Paragraph writing","titleHi":"अनुच्छेद लेखन","teach":"A paragraph has one main idea, supporting details and a closing sentence. Use linking words and check capitals and punctuation.","teachHi":"अनुच्छेद में एक मुख्य विचार, सहायक विवरण और समापन वाक्य होता है। जोड़ने वाले शब्द और विराम-चिह्न जाँचें।","example":"First, next, because and finally help connect ideas.","exampleHi":"First, next, because और finally विचार जोड़ते हैं।","question":"What should a paragraph mainly have?","options":["Many unrelated ideas","One clear main idea","No punctuation","Only a title"],"answer":1,"explain":"A paragraph develops one main idea.","explainHi":"अनुच्छेद एक मुख्य विचार को विकसित करता है।","skills":"Paragraph writing"},{"id":"g4-english-4","grade":4,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Comprehension and inference","titleHi":"बोध और निष्कर्ष","teach":"An inference combines text clues with reasonable knowledge. Distinguish what the text states from what it suggests.","teachHi":"निष्कर्ष पाठ के संकेतों और उचित ज्ञान को जोड़ता है। जो स्पष्ट लिखा है और जो संकेत मिलता है उनमें अंतर करें।","example":"Wet shoes and an umbrella may suggest that someone walked in rain.","exampleHi":"गीले जूते और छाता बारिश में चलने का संकेत दे सकते हैं।","question":"An inference is…","options":["a random guess","a conclusion from clues","a copied title","always stated directly"],"answer":1,"explain":"Inference uses clues and reasoning.","explainHi":"निष्कर्ष संकेतों और तर्क पर आधारित होता है।","skills":"Comprehension and inference"},{"id":"g4-english-5","grade":4,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Prefixes, suffixes and word meaning","titleHi":"उपसर्ग, प्रत्यय और शब्दार्थ","teach":"A prefix comes before a root; a suffix comes after it. They can change a word’s meaning or form.","teachHi":"उपसर्ग मूल शब्द से पहले और प्रत्यय बाद में आता है। ये अर्थ या शब्द-रूप बदल सकते हैं।","example":"Un + kind = unkind; teach + er = teacher.","exampleHi":"Un + kind = unkind; teach + er = teacher.","question":"What does “replay” usually mean?","options":["play again","never play","play badly","stop playing"],"answer":0,"explain":"The prefix re- can mean again.","explainHi":"Re- उपसर्ग का अर्थ फिर से हो सकता है।","skills":"Prefixes, suffixes and word meaning"},{"id":"g4-hindi-1","grade":4,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"विशेषण और क्रिया","titleHi":"Adjectives and verbs","teach":"विशेषण संज्ञा की विशेषता बताता है। क्रिया काम या अवस्था बताती है।","teachHi":"An adjective describes a noun; a verb shows an action or state.","example":"लाल फूल खिला। “लाल” विशेषण और “खिला” क्रिया है।","exampleHi":"The red flower bloomed. Red is an adjective; bloomed is a verb.","question":"“मीठा आम पका।” विशेषण कौन-सा है?","options":["आम","पका","मीठा","कोई नहीं"],"answer":2,"explain":"मीठा आम की विशेषता बताता है।","explainHi":"मीठा describes the mango.","skills":"विशेषण और क्रिया"},{"id":"g4-hindi-2","grade":4,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"काल","titleHi":"Tense","teach":"क्रिया का रूप बताता है कि काम पहले हुआ, अभी हो रहा है या आगे होगा।","teachHi":"Verb forms can show past, present or future time.","example":"कल गया, आज जाता है, कल जाएगा।","exampleHi":"Went yesterday, goes today, will go tomorrow.","question":"“मैं कल विद्यालय ___।”","options":["गया था","जाता हूँ","जाऊँगा","जाता"],"answer":2,"explain":"“कल” भविष्य के संदर्भ में “जाऊँगा” सही है।","explainHi":"For future tomorrow, जाऊँगा fits.","skills":"काल"},{"id":"g4-hindi-3","grade":4,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"मुहावरे और लोकोक्तियाँ","titleHi":"Idioms and proverbs","teach":"मुहावरे का अर्थ अक्सर शब्दों के सीधे अर्थ से अलग होता है। वाक्य के संदर्भ से अर्थ समझें।","teachHi":"Idioms often mean something beyond the literal words. Use context to understand them.","example":"“नाक में दम करना” का अर्थ बहुत परेशान करना है।","exampleHi":"“नाक में दम करना” means to trouble someone greatly.","question":"“आँखों का तारा” का अर्थ है…","options":["बहुत प्रिय","आकाश का तारा","डरावना","अनजान"],"answer":0,"explain":"यह बहुत प्रिय व्यक्ति के लिए कहा जाता है।","explainHi":"It describes someone very dear.","skills":"मुहावरे और लोकोक्तियाँ"},{"id":"g4-hindi-4","grade":4,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"अनुच्छेद लेखन","titleHi":"Paragraph writing","teach":"अनुच्छेद में एक मुख्य विषय, उससे जुड़े वाक्य और समापन होता है। वाक्यों का क्रम तार्किक रखें।","teachHi":"A paragraph has a main topic, related sentences and a closing. Keep ideas in a logical order.","example":"“मेरा विद्यालय” पर पहले परिचय, फिर सुविधाएँ और अंत में पसंद लिखें।","exampleHi":"For “My school,” introduce it, describe facilities, then conclude.","question":"अच्छे अनुच्छेद में क्या होना चाहिए?","options":["असंबंधित वाक्य","एक मुख्य विषय","कोई क्रम नहीं","केवल शीर्षक"],"answer":1,"explain":"अनुच्छेद एक मुख्य विषय पर केंद्रित होता है।","explainHi":"A paragraph focuses on one main topic.","skills":"अनुच्छेद लेखन"},{"id":"g4-hindi-5","grade":4,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"अपठित गद्यांश","titleHi":"Unseen passage","teach":"पहले पूरा गद्यांश पढ़ें, फिर प्रश्न। उत्तर छोटा, स्पष्ट और पाठ के अनुसार दें।","teachHi":"Read the whole passage first, then answer clearly using the text.","example":"मुख्य विचार पूरे अनुच्छेद को समेटता है।","exampleHi":"The main idea summarises the passage.","question":"मुख्य विचार का अर्थ है…","options":["सबसे छोटा शब्द","पूरे पाठ का प्रमुख संदेश","लेखक का नाम","केवल अंतिम पंक्ति"],"answer":1,"explain":"मुख्य विचार पूरे पाठ का केंद्रीय संदेश है।","explainHi":"The main idea is the central message.","skills":"अपठित गद्यांश"},{"id":"g4-world-1","grade":4,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Food, digestion and health","titleHi":"भोजन, पाचन और स्वास्थ्य","teach":"A balanced diet includes varied foods. Digestion breaks food into forms the body can use. Clean hands and safe water help prevent illness.","teachHi":"संतुलित आहार में विविध भोजन होता है। पाचन भोजन को शरीर के उपयोग योग्य रूप में तोड़ता है। हाथ और पानी की स्वच्छता बीमारी रोकने में मदद करती है।","example":"Wash hands with soap before eating.","exampleHi":"खाने से पहले साबुन से हाथ धोएँ।","question":"Which habit helps prevent infection?","options":["Sharing unwashed bottles","Washing hands","Leaving food uncovered","Skipping clean water"],"answer":1,"explain":"Handwashing removes many germs.","explainHi":"हाथ धोने से कई रोगाणु हटते हैं।","skills":"Food, digestion and health"},{"id":"g4-world-2","grade":4,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Materials and their properties","titleHi":"पदार्थ और उनके गुण","teach":"Materials can be compared by hardness, flexibility, transparency, absorbency and whether they conduct heat or electricity.","teachHi":"पदार्थों की कठोरता, लचक, पारदर्शिता, अवशोषण और ऊष्मा/बिजली के संचालन से तुलना की जा सकती है।","example":"Clear glass is transparent; cotton absorbs water.","exampleHi":"साफ काँच पारदर्शी है; कपास पानी सोखती है।","question":"Which material is usually absorbent?","options":["Cotton","Glass","Steel sheet","Plastic ruler"],"answer":0,"explain":"Cotton fibres absorb water.","explainHi":"कपास के रेशे पानी सोखते हैं।","skills":"Materials and their properties"},{"id":"g4-world-3","grade":4,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Force, motion and simple machines","titleHi":"बल, गति और सरल मशीनें","teach":"A push or pull is a force. Forces can change speed, direction or shape. Simple machines make some tasks easier.","teachHi":"धक्का या खिंचाव बल है। बल गति, दिशा या आकार बदल सकता है। सरल मशीनें कुछ काम आसान बनाती हैं।","example":"A ramp helps move a heavy box to a higher level.","exampleHi":"ढलान भारी डिब्बे को ऊँचाई पर ले जाना आसान करती है।","question":"Which is a push?","options":["Pulling a drawer","Pushing a door","Lifting a bag by its handle","Tugging a rope"],"answer":1,"explain":"Pushing a door applies a push force.","explainHi":"दरवाज़े को धकेलना धक्का बल है।","skills":"Force, motion and simple machines"},{"id":"g4-world-4","grade":4,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Earth, maps and directions","titleHi":"पृथ्वी, मानचित्र और दिशाएँ","teach":"Maps use symbols, labels and sometimes a scale. A compass rose shows directions. The Sun appears to rise in the east.","teachHi":"मानचित्र संकेत, नाम और कभी-कभी पैमाना उपयोग करते हैं। दिशा-सूचक दिशाएँ बताता है। सूर्य पूर्व में उगता हुआ दिखाई देता है।","example":"North is opposite south.","exampleHi":"उत्तर, दक्षिण के विपरीत है।","question":"Which direction is opposite east?","options":["North","South","West","North-east"],"answer":2,"explain":"West is opposite east.","explainHi":"पश्चिम, पूर्व के विपरीत है।","skills":"Earth, maps and directions"},{"id":"g4-world-5","grade":4,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Community, transport and communication","titleHi":"समुदाय, परिवहन और संचार","teach":"People depend on community services. Transport moves people or goods; communication shares information. Choose safe and responsible options.","teachHi":"लोग सामुदायिक सेवाओं पर निर्भर करते हैं। परिवहन लोगों/वस्तुओं को ले जाता है; संचार जानकारी साझा करता है। सुरक्षित और जिम्मेदार विकल्प चुनें।","example":"A post office helps send letters and parcels.","exampleHi":"डाकघर पत्र और पार्सल भेजने में मदद करता है।","question":"Which is a communication method?","options":["Bicycle","Letter","Bridge","Helmet"],"answer":1,"explain":"A letter communicates a message.","explainHi":"पत्र संदेश पहुँचाता है।","skills":"Community, transport and communication"},{"id":"g4-gk-1","grade":4,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Indian geography and culture","titleHi":"भारतीय भूगोल और संस्कृति","teach":"India includes mountains, plains, plateaus, deserts, coasts and islands. Cultural practices vary and deserve respect.","teachHi":"भारत में पर्वत, मैदान, पठार, रेगिस्तान, तट और द्वीप हैं। सांस्कृतिक प्रथाएँ अलग हो सकती हैं और सम्मान योग्य हैं।","example":"The Thar Desert lies mainly in north-western India.","exampleHi":"थार मरुस्थल मुख्यतः उत्तर-पश्चिम भारत में है।","question":"Which landform is very high and often steep?","options":["Plain","Mountain","Delta only","Valley only"],"answer":1,"explain":"Mountains rise high above surrounding land.","explainHi":"पर्वत आसपास की भूमि से ऊँचे होते हैं।","skills":"Indian geography and culture"},{"id":"g4-gk-2","grade":4,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Inventors and discoveries","titleHi":"आविष्कारक और खोजें","teach":"Discoveries describe finding something that exists; inventions create a device or method. Verify historical claims before repeating them.","teachHi":"खोज पहले से मौजूद चीज़ का पता लगाती है; आविष्कार उपकरण या तरीका बनाता है। ऐतिहासिक दावों को दोहराने से पहले जाँचें।","example":"A telescope helps observe distant objects.","exampleHi":"दूर की वस्तुएँ देखने में दूरबीन मदद करती है।","question":"Which tool helps view distant stars?","options":["Microscope","Telescope","Compass","Thermometer"],"answer":1,"explain":"A telescope gathers light from distant objects.","explainHi":"दूरबीन दूर की वस्तुओं का प्रकाश एकत्र करती है।","skills":"Inventors and discoveries"},{"id":"g4-gk-3","grade":4,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Civic sense and public services","titleHi":"नागरिक समझ और सार्वजनिक सेवाएँ","teach":"Public services support communities. Follow shared rules, keep public places clean and treat others fairly.","teachHi":"सार्वजनिक सेवाएँ समुदायों की मदद करती हैं। साझा नियम मानें, सार्वजनिक स्थान साफ रखें और सबके साथ न्यायपूर्ण व्यवहार करें।","example":"A library lends books and supports learning.","exampleHi":"पुस्तकालय किताबें देकर सीखने में मदद करता है।","question":"Which is responsible civic behaviour?","options":["Littering","Damaging public property","Queueing fairly","Wasting water"],"answer":2,"explain":"Fair queues respect others.","explainHi":"कतार का सम्मान दूसरों का सम्मान है।","skills":"Civic sense and public services"},{"id":"g4-gk-4","grade":4,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Media literacy","titleHi":"मीडिया साक्षरता","teach":"Ask who created a message, what evidence supports it, when it was published and whether other reliable sources agree.","teachHi":"पूछें कि संदेश किसने बनाया, प्रमाण क्या है, कब प्रकाशित हुआ और क्या अन्य भरोसेमंद स्रोत सहमत हैं।","example":"A dramatic headline alone does not prove a claim.","exampleHi":"नाटकीय शीर्षक अकेले किसी दावे का प्रमाण नहीं है।","question":"Before sharing a surprising claim, you should…","options":["share immediately","check reliable sources","trust the picture only","ignore the date"],"answer":1,"explain":"Cross-checking helps reduce misinformation.","explainHi":"स्रोतों की जाँच गलत सूचना घटाती है।","skills":"Media literacy"},{"id":"g4-gk-5","grade":4,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Reasoning and data","titleHi":"तर्क और आँकड़े","teach":"Compare data fairly and notice what is missing. A pattern can suggest a rule, but test it with more examples.","teachHi":"आँकड़ों की निष्पक्ष तुलना करें और देखें कि क्या छूटा है। पैटर्न नियम सुझा सकता है, पर अधिक उदाहरणों से जाँचें।","example":"A chart needs labels so readers know what values mean.","exampleHi":"आलेख में लेबल होने चाहिए ताकि मान समझ आएँ।","question":"Why do graphs need labels?","options":["For decoration only","To explain what data represents","To hide values","To replace data"],"answer":1,"explain":"Labels make data interpretable.","explainHi":"लेबल आँकड़ों का अर्थ स्पष्ट करते हैं।","skills":"Reasoning and data"},{"id":"g4-computer-1","grade":4,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Files, folders and typing","titleHi":"फाइल, फ़ोल्डर और टाइपिंग","teach":"Files store work; folders organise files. Use meaningful names and save work in a known place.","teachHi":"फाइल काम सहेजती है; फ़ोल्डर फाइल व्यवस्थित करता है। अर्थपूर्ण नाम दें और काम सही जगह सहेजें।","example":"“Science-notes” is clearer than “abc123”.","exampleHi":"“Science-notes”, “abc123” से स्पष्ट है।","question":"Why use folders?","options":["To organise files","To increase screen brightness","To clean a keyboard","To replace passwords"],"answer":0,"explain":"Folders organise related files.","explainHi":"फ़ोल्डर संबंधित फाइलें व्यवस्थित करते हैं।","skills":"Files, folders and typing"},{"id":"g4-computer-2","grade":4,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Online safety and privacy","titleHi":"ऑनलाइन सुरक्षा और गोपनीयता","teach":"Do not share passwords, home address or private photos with strangers. Ask a trusted adult before downloading or contacting unknown people.","teachHi":"पासवर्ड, घर का पता या निजी तस्वीरें अनजान लोगों से साझा न करें। डाउनलोड या संपर्क से पहले भरोसेमंद बड़े से पूछें।","example":"A strong password is private and hard to guess.","exampleHi":"मजबूत पासवर्ड निजी और अनुमान लगाना कठिन होता है।","question":"What should remain private?","options":["Your password","A public library address","A class topic","A public weather report"],"answer":0,"explain":"Passwords protect accounts and should not be shared.","explainHi":"पासवर्ड खाते की रक्षा करते हैं और साझा नहीं करने चाहिए।","skills":"Online safety and privacy"},{"id":"g4-computer-3","grade":4,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Algorithms and debugging","titleHi":"एल्गोरिद्म और त्रुटि सुधार","teach":"An algorithm is a clear sequence of steps. Debugging means finding and fixing an error by testing one step at a time.","teachHi":"एल्गोरिद्म स्पष्ट चरणों का क्रम है। डिबगिंग में एक-एक चरण जाँचकर गलती खोजते और सुधारते हैं।","example":"A recipe is an algorithm for making food.","exampleHi":"रेसिपी भोजन बनाने का एल्गोरिद्म है।","question":"Debugging means…","options":["adding random steps","finding and fixing errors","deleting all files","turning off learning"],"answer":1,"explain":"Debugging finds and fixes mistakes.","explainHi":"डिबगिंग गलतियाँ खोजकर सुधारती है।","skills":"Algorithms and debugging"},{"id":"g4-computer-4","grade":4,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Computer basics","titleHi":"कंप्यूटर की मूल बातें","teach":"A computer takes input, processes it, stores data and gives output. Different devices serve different purposes.","teachHi":"कंप्यूटर इनपुट लेता है, प्रक्रिया करता है, डेटा रखता है और आउटपुट देता है। अलग उपकरण अलग काम करते हैं।","example":"Keyboard = input; monitor = output.","exampleHi":"कीबोर्ड इनपुट और मॉनिटर आउटपुट है।","question":"Which is an input device?","options":["Monitor","Speaker","Keyboard","Printer"],"answer":2,"explain":"A keyboard sends information into a computer.","explainHi":"कीबोर्ड कंप्यूटर में जानकारी देता है।","skills":"Computer basics"},{"id":"g4-art-1","grade":4,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Health, movement and teamwork","titleHi":"स्वास्थ्य, गतिविधि और टीमवर्क","teach":"Movement, rest, hydration and balanced food support wellbeing. In games, cooperate, take turns and follow safety rules.","teachHi":"गतिविधि, आराम, पानी और संतुलित भोजन स्वास्थ्य में मदद करते हैं। खेल में सहयोग करें, बारी लें और सुरक्षा नियम मानें।","example":"Warm up before vigorous exercise.","exampleHi":"तेज़ व्यायाम से पहले वार्म-अप करें।","question":"What is a good practice before vigorous exercise?","options":["Warm up","Skip water always","Ignore pain","Push others"],"answer":0,"explain":"Warming up prepares the body for movement.","explainHi":"वार्म-अप शरीर को गतिविधि के लिए तैयार करता है।","skills":"Health, movement and teamwork"},{"id":"g4-art-2","grade":4,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Life skills and study habits","titleHi":"जीवन कौशल और अध्ययन आदतें","teach":"Break a large task into smaller steps, take short breaks, ask for help and review mistakes without shame.","teachHi":"बड़े काम को छोटे चरणों में बाँटें, छोटे विराम लें, मदद माँगें और बिना शर्म के गलतियों की समीक्षा करें।","example":"Study 25–30 minutes, then take a short movement break.","exampleHi":"25–30 मिनट पढ़ें, फिर थोड़ा चलने का विराम लें।","question":"When you make a mistake, the best next step is…","options":["give up","review why and try again","hide all work","blame a friend"],"answer":1,"explain":"Mistakes give information about what to practise next.","explainHi":"गलतियाँ बताती हैं कि आगे किसका अभ्यास करना है।","skills":"Life skills and study habits"},{"id":"g4-art-3","grade":4,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Art, music and observation","titleHi":"कला, संगीत और अवलोकन","teach":"Artists observe shape, line, colour, pattern and texture. Creative work can have many valid solutions; explain your choices.","teachHi":"कलाकार आकार, रेखा, रंग, पैटर्न और बनावट देखते हैं। रचनात्मक काम के कई सही तरीके हो सकते हैं; अपने चुनाव समझाएँ।","example":"Repeating shapes creates a pattern.","exampleHi":"आकार दोहराने से पैटर्न बनता है।","question":"Which element describes how a surface feels or looks?","options":["Texture","Date","Weight only","Address"],"answer":0,"explain":"Texture describes surface quality.","explainHi":"बनावट सतह का गुण बताती है।","skills":"Art, music and observation"},{"id":"g4-art-4","grade":4,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Health, movement and teamwork","titleHi":"स्वास्थ्य, गतिविधि और टीमवर्क","teach":"Movement, rest, hydration and balanced food support wellbeing. In games, cooperate, take turns and follow safety rules.","teachHi":"गतिविधि, आराम, पानी और संतुलित भोजन स्वास्थ्य में मदद करते हैं। खेल में सहयोग करें, बारी लें और सुरक्षा नियम मानें।","example":"Warm up before vigorous exercise.","exampleHi":"तेज़ व्यायाम से पहले वार्म-अप करें।","question":"What is a good practice before vigorous exercise?","options":["Warm up","Skip water always","Ignore pain","Push others"],"answer":0,"explain":"Warming up prepares the body for movement.","explainHi":"वार्म-अप शरीर को गतिविधि के लिए तैयार करता है।","skills":"Health, movement and teamwork"},{"id":"g5-math-1","grade":5,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Large numbers and rounding","titleHi":"बड़ी संख्याएँ और पूर्णांकन","teach":"Round by checking the digit immediately to the right of the place. 5 or more rounds up; 4 or less stays.","teachHi":"किसी स्थान तक पूर्णांकित करते समय उसके दाईं ओर का अंक देखें। 5 या अधिक पर बढ़ाएँ; 4 या कम पर वही रखें।","example":"6,748 rounded to the nearest hundred is 6,700.","exampleHi":"6,748 को निकटतम सैकड़े तक करने पर 6,700।","question":"Round 3,672 to the nearest hundred.","options":["3,600","3,670","3,700","4,000"],"answer":2,"explain":"The tens digit is 7, so 3,600 rounds up to 3,700.","explainHi":"दहाई का अंक 7 है, इसलिए 3,600 बढ़कर 3,700 होगा।","skills":"Large numbers and rounding"},{"id":"g5-math-2","grade":5,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Factors and multiples","titleHi":"गुणनखंड और गुणज","teach":"A factor divides a number exactly. A multiple is found by multiplying a number by whole numbers.","teachHi":"गुणनखंड किसी संख्या को पूरा-पूरा विभाजित करता है। गुणज किसी संख्या को पूर्ण संख्याओं से गुणा करके मिलते हैं।","example":"Factors of 12 include 1, 2, 3, 4, 6 and 12.","exampleHi":"12 के गुणनखंड 1, 2, 3, 4, 6 और 12 हैं।","question":"Which is a multiple of 7?","options":["20","28","30","32"],"answer":1,"explain":"7 × 4 = 28.","explainHi":"7 × 4 = 28।","skills":"Factors and multiples"},{"id":"g5-math-3","grade":5,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Fractions and decimals","titleHi":"भिन्न और दशमलव","teach":"Fractions and decimals can represent the same value. Tenths are one place after the decimal point; hundredths are two places after it.","teachHi":"भिन्न और दशमलव एक ही मान दिखा सकते हैं। दशांश दशमलव के बाद पहले स्थान और शतांश दूसरे स्थान पर होता है।","example":"0.5 = 5/10 = 1/2.","exampleHi":"0.5 = 5/10 = 1/2।","question":"Which decimal equals 3/10?","options":["0.03","0.3","3.0","30"],"answer":1,"explain":"Three tenths is written 0.3.","explainHi":"तीन दशांश 0.3 लिखा जाता है।","skills":"Fractions and decimals"},{"id":"g5-math-4","grade":5,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Area, perimeter and volume ideas","titleHi":"क्षेत्रफल, परिमाप और आयतन","teach":"Use perimeter for the boundary, area for a flat surface, and volume for space occupied by a solid.","teachHi":"सीमा के लिए परिमाप, समतल सतह के लिए क्षेत्रफल और ठोस द्वारा घेरी जगह के लिए आयतन उपयोग करें।","example":"A 6 cm × 4 cm rectangle has area 24 square cm.","exampleHi":"6 सेमी × 4 सेमी आयत का क्षेत्रफल 24 वर्ग सेमी है।","question":"Area of a 7 cm by 3 cm rectangle?","options":["10 cm²","20 cm²","21 cm²","24 cm²"],"answer":2,"explain":"Area = length × width = 7 × 3 = 21 cm².","explainHi":"क्षेत्रफल = लंबाई × चौड़ाई = 7 × 3 = 21 वर्ग सेमी।","skills":"Area, perimeter and volume ideas"},{"id":"g5-math-5","grade":5,"subject":"math","subjectEn":"Mathematics","subjectHi":"गणित","icon":"🔢","title":"Patterns and problem solving","titleHi":"पैटर्न और समस्या समाधान","teach":"Represent a problem with a drawing, table or number sentence. Check that the answer fits the story and units.","teachHi":"समस्या को चित्र, तालिका या संख्या-वाक्य से दिखाएँ। जाँचें कि उत्तर कहानी और इकाइयों से मेल खाता है।","example":"If 3 notebooks cost ₹45, one costs ₹15.","exampleHi":"यदि 3 कॉपियों की कीमत ₹45 है, तो एक की ₹15।","question":"Five identical pens cost ₹60. One pen costs…","options":["₹10","₹12","₹15","₹20"],"answer":1,"explain":"60 ÷ 5 = ₹12.","explainHi":"60 ÷ 5 = ₹12।","skills":"Patterns and problem solving"},{"id":"g5-english-1","grade":5,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Complex sentences and conjunctions","titleHi":"जटिल वाक्य और संयोजक","teach":"Conjunctions join words or clauses. Because gives a reason; although shows contrast; and adds information.","teachHi":"Conjunction शब्दों या उपवाक्यों को जोड़ते हैं। Because कारण, although विरोध और and अतिरिक्त जानकारी देता है।","example":"I stayed inside because it rained.","exampleHi":"बारिश हुई, इसलिए मैं अंदर रहा।","question":"Which word best completes: “I was tired, ___ I finished my work”?","options":["but","because","or","until"],"answer":0,"explain":"But shows contrast between being tired and finishing.","explainHi":"But थकान और काम पूरा करने के बीच विरोध दिखाता है।","skills":"Complex sentences and conjunctions"},{"id":"g5-english-2","grade":5,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Direct and reported speech","titleHi":"प्रत्यक्ष और अप्रत्यक्ष कथन","teach":"Direct speech gives exact words in quotation marks. Reported speech tells what someone said and may change pronouns or time words.","teachHi":"प्रत्यक्ष कथन में ठीक शब्द उद्धरण चिह्नों में होते हैं। अप्रत्यक्ष कथन कही गई बात बताता है और सर्वनाम/समय बदल सकते हैं।","example":"“I am ready,” said Ravi. Ravi said that he was ready.","exampleHi":"“I am ready,” said Ravi. Ravi said that he was ready.","question":"Which uses direct speech?","options":["Ravi said he was ready.","Ravi said that he is ready.","“I am ready,” said Ravi.","Ravi was ready."],"answer":2,"explain":"Quotation marks show the speaker’s exact words.","explainHi":"उद्धरण चिह्न वक्ता के ठीक शब्द दिखाते हैं।","skills":"Direct and reported speech"},{"id":"g5-english-3","grade":5,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Writing a clear answer","titleHi":"स्पष्ट उत्तर लेखन","teach":"Answer the exact question. Use a complete sentence, include evidence when asked, and check spelling and punctuation.","teachHi":"प्रश्न का ठीक उत्तर दें। पूरा वाक्य लिखें, माँगे जाने पर प्रमाण दें और वर्तनी जाँचें।","example":"For “Why did the plant wilt?” state a reason from the passage.","exampleHi":"“पौधा क्यों मुरझाया?” के लिए पाठ से कारण लिखें।","question":"A strong comprehension answer should…","options":["ignore the question","include relevant evidence","be unrelated","always be one word"],"answer":1,"explain":"Evidence supports the answer.","explainHi":"प्रमाण उत्तर का समर्थन करता है।","skills":"Writing a clear answer"},{"id":"g5-english-4","grade":5,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Figurative language","titleHi":"अलंकारिक भाषा","teach":"A simile compares using like or as. A metaphor says one thing is another. Personification gives human qualities to non-human things.","teachHi":"उपमा में like/as से तुलना होती है। रूपक एक चीज़ को दूसरी बताता है। मानवीकरण निर्जीव चीज़ों को मानवीय गुण देता है।","example":"“The wind whispered” is personification.","exampleHi":"“The wind whispered” मानवीकरण है।","question":"“As brave as a lion” is a…","options":["simile","question","command","rhyme only"],"answer":0,"explain":"It compares using “as”.","explainHi":"इसमें “as” से तुलना की गई है।","skills":"Figurative language"},{"id":"g5-english-5","grade":5,"subject":"english","subjectEn":"English","subjectHi":"अंग्रेज़ी","icon":"📘","title":"Vocabulary in context","titleHi":"संदर्भ में शब्दार्थ","teach":"Use nearby words and the situation to infer unfamiliar words. Check whether the inferred meaning fits the whole sentence.","teachHi":"आसपास के शब्दों और परिस्थिति से नए शब्द का अर्थ समझें। जाँचें कि अर्थ पूरे वाक्य में ठीक बैठता है।","example":"“The arid land had no rain” suggests arid means very dry.","exampleHi":"“The arid land had no rain” से arid का अर्थ बहुत सूखा समझ आता है।","question":"In “The fragile glass broke easily,” fragile means…","options":["heavy","easily broken","colourful","waterproof"],"answer":1,"explain":"The glass broke easily, so fragile means easily broken.","explainHi":"गिलास आसानी से टूटा, इसलिए fragile का अर्थ आसानी से टूटने वाला है।","skills":"Vocabulary in context"},{"id":"g5-hindi-1","grade":5,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"सर्वनाम, क्रिया-विशेषण और संबंधबोधक","titleHi":"Pronouns, adverbs and postpositions","teach":"सर्वनाम संज्ञा की जगह आता है। क्रिया-विशेषण क्रिया की विशेषता बताता है। संबंधबोधक शब्दों के संबंध बताते हैं।","teachHi":"Pronouns replace nouns, adverbs describe actions, and postpositions show relationships.","example":"वह धीरे चलता है। “धीरे” क्रिया-विशेषण है।","exampleHi":"He walks slowly. “Slowly” is an adverb.","question":"“रीमा तेज दौड़ती है।” क्रिया-विशेषण है…","options":["रीमा","दौड़ती","तेज","है"],"answer":2,"explain":"तेज दौड़ने के ढंग को बताता है।","explainHi":"तेज describes how she runs.","skills":"सर्वनाम, क्रिया-विशेषण और संबंधबोधक"},{"id":"g5-hindi-2","grade":5,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"वाक्य-रचना और विराम","titleHi":"Sentence structure and punctuation","teach":"वाक्य में शब्दों का क्रम अर्थ स्पष्ट करता है। अल्पविराम, पूर्णविराम और उद्धरण चिह्न सही जगह लगाएँ।","teachHi":"Word order makes meaning clear. Use commas, full stops and quotation marks correctly.","example":"राम ने कहा, “मैं तैयार हूँ।”","exampleHi":"Ram said, “I am ready.”","question":"किस चिह्न से किसी के ठीक शब्द दिखाए जाते हैं?","options":["उद्धरण चिह्न","अल्पविराम ही","कोष्ठक ही","प्रश्नवाचक चिह्न"],"answer":0,"explain":"उद्धरण चिह्न ठीक बोले गए शब्द दिखाते हैं।","explainHi":"Quotation marks show exact words.","skills":"वाक्य-रचना और विराम"},{"id":"g5-hindi-3","grade":5,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"पत्र और ईमेल लेखन","titleHi":"Letter and email writing","teach":"पत्र में संबोधन, विषयानुसार मुख्य भाग और उचित समापन रखें। भाषा स्पष्ट और विनम्र हो।","teachHi":"A letter needs a greeting, relevant body and suitable closing. Keep it clear and polite.","example":"छुट्टी के आवेदन में कारण और तारीख स्पष्ट लिखें।","exampleHi":"A leave application should state the reason and date clearly.","question":"औपचारिक पत्र में भाषा कैसी होनी चाहिए?","options":["अस्पष्ट","विनम्र और स्पष्ट","केवल बोलचाल","असंबंधित"],"answer":1,"explain":"औपचारिक पत्र विनम्र और स्पष्ट होता है।","explainHi":"Formal writing should be polite and clear.","skills":"पत्र और ईमेल लेखन"},{"id":"g5-hindi-4","grade":5,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"पर्यायवाची, विलोम और अनेकर्थी","titleHi":"Synonyms, antonyms and multiple meanings","teach":"शब्दों का अर्थ संदर्भ के अनुसार समझें। एक शब्द के अनेक अर्थ हो सकते हैं।","teachHi":"Interpret words in context; one word can have multiple meanings.","example":"“कल” का अर्थ बीता हुआ या आने वाला दिन हो सकता है।","exampleHi":"“Kal” can mean yesterday or tomorrow depending on context.","question":"“आरंभ” का पर्यायवाची है…","options":["अंत","शुरुआत","विराम","विलंब"],"answer":1,"explain":"आरंभ और शुरुआत समान अर्थ रखते हैं।","explainHi":"आरंभ and शुरुआत are synonyms.","skills":"पर्यायवाची, विलोम और अनेकर्थी"},{"id":"g5-hindi-5","grade":5,"subject":"hindi","subjectEn":"Hindi","subjectHi":"हिंदी","icon":"🔤","title":"सारांश और विचार लेखन","titleHi":"Summary and opinion writing","teach":"सारांश में मुख्य बातें अपने शब्दों में संक्षेप में लिखें। राय देते समय कारण या उदाहरण दें।","teachHi":"Summarise key ideas briefly in your own words. Support an opinion with reasons or examples.","example":"कहानी का सार मुख्य घटना और परिणाम बताता है।","exampleHi":"A story summary gives the main event and outcome.","question":"अच्छी राय के साथ क्या होना चाहिए?","options":["कारण या उदाहरण","असंबंधित तथ्य","केवल नकल","कोई स्पष्टता नहीं"],"answer":0,"explain":"कारण या उदाहरण राय को मजबूत बनाते हैं।","explainHi":"Reasons or examples support an opinion.","skills":"सारांश और विचार लेखन"},{"id":"g5-world-1","grade":5,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Human body and healthy systems","titleHi":"मानव शरीर और स्वस्थ प्रणालियाँ","teach":"Body systems work together. The lungs help exchange gases, the heart pumps blood, and the digestive system processes food.","teachHi":"शरीर की प्रणालियाँ मिलकर काम करती हैं। फेफड़े गैसों का आदान-प्रदान, हृदय रक्त पंप और पाचन तंत्र भोजन संसाधित करता है।","example":"Exercise and sleep support health.","exampleHi":"व्यायाम और नींद स्वास्थ्य में मदद करते हैं।","question":"Which organ pumps blood?","options":["Lungs","Heart","Stomach","Kidney"],"answer":1,"explain":"The heart pumps blood around the body.","explainHi":"हृदय शरीर में रक्त पंप करता है।","skills":"Human body and healthy systems"},{"id":"g5-world-2","grade":5,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Matter, mixtures and changes","titleHi":"पदार्थ, मिश्रण और परिवर्तन","teach":"Matter has mass and occupies space. Some changes are reversible, such as melting ice; others form new substances.","teachHi":"पदार्थ का द्रव्यमान होता है और वह जगह घेरता है। कुछ परिवर्तन उलटे जा सकते हैं, जैसे बर्फ पिघलना; कुछ में नए पदार्थ बनते हैं।","example":"Salt dissolving in water forms a mixture.","exampleHi":"पानी में नमक घुलने से मिश्रण बनता है।","question":"Which change is usually reversible?","options":["Burning paper","Cooking an egg","Melting ice","Rusting iron"],"answer":2,"explain":"Melted water can be frozen again.","explainHi":"पिघले पानी को फिर जमाया जा सकता है।","skills":"Matter, mixtures and changes"},{"id":"g5-world-3","grade":5,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Energy, light and sound","titleHi":"ऊर्जा, प्रकाश और ध्वनि","teach":"Light travels from a source and can be reflected. Sound is produced by vibrations and travels through a medium.","teachHi":"प्रकाश स्रोत से आता है और परावर्तित हो सकता है। ध्वनि कंपन से बनती है और माध्यम से चलती है।","example":"A mirror reflects light.","exampleHi":"दर्पण प्रकाश परावर्तित करता है।","question":"Sound is produced by…","options":["vibrations","shadows","stillness","colour"],"answer":0,"explain":"Vibrating objects produce sound.","explainHi":"कंपन करने वाली वस्तुएँ ध्वनि उत्पन्न करती हैं।","skills":"Energy, light and sound"},{"id":"g5-world-4","grade":5,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"Earth, resources and environment","titleHi":"पृथ्वी, संसाधन और पर्यावरण","teach":"Resources include water, soil, air and energy. Reduce waste, reuse materials and recycle suitable items to conserve resources.","teachHi":"संसाधनों में पानी, मिट्टी, हवा और ऊर्जा शामिल हैं। संसाधन बचाने के लिए कचरा घटाएँ, पुनः उपयोग करें और उपयुक्त वस्तुएँ पुनर्चक्रित करें।","example":"Composting fruit peels can return nutrients to soil.","exampleHi":"फल के छिलकों की खाद मिट्टी में पोषक तत्व लौटाती है।","question":"Which action conserves resources?","options":["Waste food","Leave lights on","Reuse a notebook carefully","Pollute a stream"],"answer":2,"explain":"Reusing a notebook reduces waste.","explainHi":"कॉपी का पुनः उपयोग कचरा घटाता है।","skills":"Earth, resources and environment"},{"id":"g5-world-5","grade":5,"subject":"world","subjectEn":"World Around Us / Science & Social Studies","subjectHi":"हमारा परिवेश / विज्ञान व सामाजिक अध्ययन","icon":"🌍","title":"India: geography, heritage and citizenship","titleHi":"भारत: भूगोल, विरासत और नागरिकता","teach":"India has varied landforms, languages and traditions. Maps locate places; citizens can help communities by respecting rules and diversity.","teachHi":"भारत में विविध भू-आकृतियाँ, भाषाएँ और परंपराएँ हैं। मानचित्र स्थान बताते हैं; नियमों और विविधता का सम्मान समुदाय की मदद करता है।","example":"The Himalayas are a major mountain range in northern India.","exampleHi":"हिमालय उत्तर भारत की प्रमुख पर्वतमाला है।","question":"Which tool helps locate a place?","options":["Map","Thermometer","Balance","Clock only"],"answer":0,"explain":"Maps show locations and spatial relationships.","explainHi":"मानचित्र स्थान और उनके संबंध दिखाते हैं।","skills":"India: geography, heritage and citizenship"},{"id":"g5-gk-1","grade":5,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"World geography and environment","titleHi":"विश्व भूगोल और पर्यावरण","teach":"Continents and oceans organise global geography. Climate describes long-term patterns; weather describes short-term conditions.","teachHi":"महाद्वीप और महासागर विश्व भूगोल को व्यवस्थित करते हैं। जलवायु दीर्घकालीन पैटर्न और मौसम अल्पकालीन स्थिति है।","example":"A rainy afternoon is weather, not a full climate description.","exampleHi":"एक बरसाती दोपहर मौसम है, पूरी जलवायु का वर्णन नहीं।","question":"Climate refers mainly to…","options":["today’s weather","long-term weather patterns","one cloud","one storm only"],"answer":1,"explain":"Climate is the long-term pattern.","explainHi":"जलवायु दीर्घकालीन पैटर्न है।","skills":"World geography and environment"},{"id":"g5-gk-2","grade":5,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"History and heritage","titleHi":"इतिहास और विरासत","teach":"History uses evidence such as objects, buildings, records and oral accounts. Sources can have different perspectives.","teachHi":"इतिहास वस्तुओं, इमारतों, अभिलेखों और मौखिक विवरणों जैसे प्रमाणों का उपयोग करता है। स्रोतों के दृष्टिकोण अलग हो सकते हैं।","example":"An old coin can provide clues about trade and rulers.","exampleHi":"पुराना सिक्का व्यापार और शासकों के संकेत दे सकता है।","question":"Which is a historical source?","options":["A dated inscription","A random guess","An unlabelled rumour","A future prediction"],"answer":0,"explain":"An inscription can provide evidence from the past.","explainHi":"अभिलेख अतीत का प्रमाण दे सकता है।","skills":"History and heritage"},{"id":"g5-gk-3","grade":5,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Government, rights and responsibilities","titleHi":"सरकार, अधिकार और जिम्मेदारियाँ","teach":"Rules help people live together. Rights go with responsibilities, including respecting others and protecting shared resources.","teachHi":"नियम लोगों को साथ रहने में मदद करते हैं। अधिकारों के साथ जिम्मेदारियाँ भी हैं, जैसे दूसरों का सम्मान और साझा संसाधनों की रक्षा।","example":"Keeping a public place clean is a shared responsibility.","exampleHi":"सार्वजनिक स्थान साफ रखना साझा जिम्मेदारी है।","question":"Which action supports a community?","options":["Damaging a park","Respecting public rules","Blocking a path","Wasting shared water"],"answer":1,"explain":"Respecting rules supports everyone.","explainHi":"नियमों का सम्मान सभी की मदद करता है।","skills":"Government, rights and responsibilities"},{"id":"g5-gk-4","grade":5,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Scientific thinking and evidence","titleHi":"वैज्ञानिक सोच और प्रमाण","teach":"A strong explanation uses evidence, separates observation from opinion and remains open to correction when new evidence appears.","teachHi":"अच्छी व्याख्या प्रमाण का उपयोग करती है, अवलोकन और राय अलग रखती है और नए प्रमाण पर सुधार स्वीकारती है।","example":"Measure plant growth over several days instead of relying on memory.","exampleHi":"याद पर निर्भर रहने के बजाय कई दिनों तक पौधे की वृद्धि मापें।","question":"Which is strongest evidence for faster growth?","options":["A guess","One vague memory","Repeated measurements","A popular opinion"],"answer":2,"explain":"Repeated measurements are more reliable.","explainHi":"बार-बार मापना अधिक भरोसेमंद है।","skills":"Scientific thinking and evidence"},{"id":"g5-gk-5","grade":5,"subject":"gk","subjectEn":"General Knowledge & Reasoning","subjectHi":"सामान्य ज्ञान व तर्क","icon":"🧠","title":"Computing and digital citizenship","titleHi":"कंप्यूटिंग और डिजिटल नागरिकता","teach":"Algorithms are ordered steps. Digital citizens protect privacy, communicate respectfully and credit creators.","teachHi":"एल्गोरिद्म क्रमबद्ध चरण हैं। डिजिटल नागरिक गोपनीयता बचाते हैं, सम्मानपूर्वक बात करते हैं और रचनाकार को श्रेय देते हैं।","example":"A recipe is an everyday example of ordered instructions.","exampleHi":"रेसिपी क्रमबद्ध निर्देशों का रोज़मर्रा का उदाहरण है।","question":"An algorithm is…","options":["a random picture","ordered steps to solve a task","a password only","a computer screen"],"answer":1,"explain":"Algorithms describe ordered steps.","explainHi":"एल्गोरिद्म क्रमबद्ध चरण बताते हैं।","skills":"Computing and digital citizenship"},{"id":"g5-computer-1","grade":5,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Online safety and privacy","titleHi":"ऑनलाइन सुरक्षा और गोपनीयता","teach":"Do not share passwords, home address or private photos with strangers. Ask a trusted adult before downloading or contacting unknown people.","teachHi":"पासवर्ड, घर का पता या निजी तस्वीरें अनजान लोगों से साझा न करें। डाउनलोड या संपर्क से पहले भरोसेमंद बड़े से पूछें।","example":"A strong password is private and hard to guess.","exampleHi":"मजबूत पासवर्ड निजी और अनुमान लगाना कठिन होता है।","question":"What should remain private?","options":["Your password","A public library address","A class topic","A public weather report"],"answer":0,"explain":"Passwords protect accounts and should not be shared.","explainHi":"पासवर्ड खाते की रक्षा करते हैं और साझा नहीं करने चाहिए।","skills":"Online safety and privacy"},{"id":"g5-computer-2","grade":5,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Algorithms and debugging","titleHi":"एल्गोरिद्म और त्रुटि सुधार","teach":"An algorithm is a clear sequence of steps. Debugging means finding and fixing an error by testing one step at a time.","teachHi":"एल्गोरिद्म स्पष्ट चरणों का क्रम है। डिबगिंग में एक-एक चरण जाँचकर गलती खोजते और सुधारते हैं।","example":"A recipe is an algorithm for making food.","exampleHi":"रेसिपी भोजन बनाने का एल्गोरिद्म है।","question":"Debugging means…","options":["adding random steps","finding and fixing errors","deleting all files","turning off learning"],"answer":1,"explain":"Debugging finds and fixes mistakes.","explainHi":"डिबगिंग गलतियाँ खोजकर सुधारती है।","skills":"Algorithms and debugging"},{"id":"g5-computer-3","grade":5,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Computer basics","titleHi":"कंप्यूटर की मूल बातें","teach":"A computer takes input, processes it, stores data and gives output. Different devices serve different purposes.","teachHi":"कंप्यूटर इनपुट लेता है, प्रक्रिया करता है, डेटा रखता है और आउटपुट देता है। अलग उपकरण अलग काम करते हैं।","example":"Keyboard = input; monitor = output.","exampleHi":"कीबोर्ड इनपुट और मॉनिटर आउटपुट है।","question":"Which is an input device?","options":["Monitor","Speaker","Keyboard","Printer"],"answer":2,"explain":"A keyboard sends information into a computer.","explainHi":"कीबोर्ड कंप्यूटर में जानकारी देता है।","skills":"Computer basics"},{"id":"g5-computer-4","grade":5,"subject":"computer","subjectEn":"Computing & Digital Safety","subjectHi":"कंप्यूटिंग व डिजिटल सुरक्षा","icon":"💻","title":"Files, folders and typing","titleHi":"फाइल, फ़ोल्डर और टाइपिंग","teach":"Files store work; folders organise files. Use meaningful names and save work in a known place.","teachHi":"फाइल काम सहेजती है; फ़ोल्डर फाइल व्यवस्थित करता है। अर्थपूर्ण नाम दें और काम सही जगह सहेजें।","example":"“Science-notes” is clearer than “abc123”.","exampleHi":"“Science-notes”, “abc123” से स्पष्ट है।","question":"Why use folders?","options":["To organise files","To increase screen brightness","To clean a keyboard","To replace passwords"],"answer":0,"explain":"Folders organise related files.","explainHi":"फ़ोल्डर संबंधित फाइलें व्यवस्थित करते हैं।","skills":"Files, folders and typing"},{"id":"g5-art-1","grade":5,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Life skills and study habits","titleHi":"जीवन कौशल और अध्ययन आदतें","teach":"Break a large task into smaller steps, take short breaks, ask for help and review mistakes without shame.","teachHi":"बड़े काम को छोटे चरणों में बाँटें, छोटे विराम लें, मदद माँगें और बिना शर्म के गलतियों की समीक्षा करें।","example":"Study 25–30 minutes, then take a short movement break.","exampleHi":"25–30 मिनट पढ़ें, फिर थोड़ा चलने का विराम लें।","question":"When you make a mistake, the best next step is…","options":["give up","review why and try again","hide all work","blame a friend"],"answer":1,"explain":"Mistakes give information about what to practise next.","explainHi":"गलतियाँ बताती हैं कि आगे किसका अभ्यास करना है।","skills":"Life skills and study habits"},{"id":"g5-art-2","grade":5,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Art, music and observation","titleHi":"कला, संगीत और अवलोकन","teach":"Artists observe shape, line, colour, pattern and texture. Creative work can have many valid solutions; explain your choices.","teachHi":"कलाकार आकार, रेखा, रंग, पैटर्न और बनावट देखते हैं। रचनात्मक काम के कई सही तरीके हो सकते हैं; अपने चुनाव समझाएँ।","example":"Repeating shapes creates a pattern.","exampleHi":"आकार दोहराने से पैटर्न बनता है।","question":"Which element describes how a surface feels or looks?","options":["Texture","Date","Weight only","Address"],"answer":0,"explain":"Texture describes surface quality.","explainHi":"बनावट सतह का गुण बताती है।","skills":"Art, music and observation"},{"id":"g5-art-3","grade":5,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Health, movement and teamwork","titleHi":"स्वास्थ्य, गतिविधि और टीमवर्क","teach":"Movement, rest, hydration and balanced food support wellbeing. In games, cooperate, take turns and follow safety rules.","teachHi":"गतिविधि, आराम, पानी और संतुलित भोजन स्वास्थ्य में मदद करते हैं। खेल में सहयोग करें, बारी लें और सुरक्षा नियम मानें।","example":"Warm up before vigorous exercise.","exampleHi":"तेज़ व्यायाम से पहले वार्म-अप करें।","question":"What is a good practice before vigorous exercise?","options":["Warm up","Skip water always","Ignore pain","Push others"],"answer":0,"explain":"Warming up prepares the body for movement.","explainHi":"वार्म-अप शरीर को गतिविधि के लिए तैयार करता है।","skills":"Health, movement and teamwork"},{"id":"g5-art-4","grade":5,"subject":"art","subjectEn":"Art, Health & Life Skills","subjectHi":"कला, स्वास्थ्य व जीवन कौशल","icon":"🎨","title":"Life skills and study habits","titleHi":"जीवन कौशल और अध्ययन आदतें","teach":"Break a large task into smaller steps, take short breaks, ask for help and review mistakes without shame.","teachHi":"बड़े काम को छोटे चरणों में बाँटें, छोटे विराम लें, मदद माँगें और बिना शर्म के गलतियों की समीक्षा करें।","example":"Study 25–30 minutes, then take a short movement break.","exampleHi":"25–30 मिनट पढ़ें, फिर थोड़ा चलने का विराम लें।","question":"When you make a mistake, the best next step is…","options":["give up","review why and try again","hide all work","blame a friend"],"answer":1,"explain":"Mistakes give information about what to practise next.","explainHi":"गलतियाँ बताती हैं कि आगे किसका अभ्यास करना है।","skills":"Life skills and study habits"}];
